-- C1 ORDINARY DETAIL CONCURRENCY FIXTURE
select
  (select count(*)::integer from public.project_cost_items where tenant_id='c1f10000-0000-4000-8000-000000000010' and company_id='c1f10000-0000-4000-8000-000000000020' and project_id='c1f10000-0000-4000-8000-000000000102' and cost_category_id='c1f10000-0000-4000-8000-000000000301') as parent_count,
  (select count(*)::integer from public.project_cost_item_details detail join public.project_cost_items item on item.id=detail.project_cost_item_id where item.tenant_id='c1f10000-0000-4000-8000-000000000010' and item.company_id='c1f10000-0000-4000-8000-000000000020' and item.project_id='c1f10000-0000-4000-8000-000000000102' and item.cost_category_id='c1f10000-0000-4000-8000-000000000301') as detail_count,
  (select count(*)::integer from public.project_cost_item_details detail join public.project_cost_items item on item.id=detail.project_cost_item_id where item.tenant_id='c1f10000-0000-4000-8000-000000000010' and item.company_id='c1f10000-0000-4000-8000-000000000020' and item.project_id='c1f10000-0000-4000-8000-000000000102' and item.cost_category_id='c1f10000-0000-4000-8000-000000000301' and detail.publication_state='published') as published_count,
  (select count(distinct detail.line_no)::integer from public.project_cost_item_details detail join public.project_cost_items item on item.id=detail.project_cost_item_id where item.tenant_id='c1f10000-0000-4000-8000-000000000010' and item.company_id='c1f10000-0000-4000-8000-000000000020' and item.project_id='c1f10000-0000-4000-8000-000000000102' and item.cost_category_id='c1f10000-0000-4000-8000-000000000301') as distinct_line_count,
  (select amount_text from public.project_cost_items where tenant_id='c1f10000-0000-4000-8000-000000000010' and company_id='c1f10000-0000-4000-8000-000000000020' and project_id='c1f10000-0000-4000-8000-000000000102' and cost_category_id='c1f10000-0000-4000-8000-000000000301') as amount_text,
  (select count(*)::integer from public.cost_command_receipts where tenant_id='c1f10000-0000-4000-8000-000000000010' and company_id='c1f10000-0000-4000-8000-000000000020' and command_name='project_cost_detail.create_and_publish') as direct_receipt_count,
  (select count(*)::integer from public.audit_events where tenant_id='c1f10000-0000-4000-8000-000000000010' and company_id='c1f10000-0000-4000-8000-000000000020' and action='c1.project_cost_detail.created_and_published') as direct_audit_count;
